    if (text[index] === targetChar) {
      return true;
    }
  }

  return false;
}

function chooseQuote(text) {
  const hasSingleQuote = containsChar(text, "'");
  const hasDoubleQuote = containsChar(text, '"');

  if (hasSingleQuote && !hasDoubleQuote) {
    return '"';
  }

  return "'";
}

function escapeChar(ch, quote) {
  if (ch === '\\') {
    return '\\\\';
  }

  if (ch === quote) {
    return `\\${quote}`;
  }

  if (ch === '\t') {
    return '\\t';
  }

  if (ch === '\n') {
    return '\\n';
  }

  if (ch === '\r') {
    return '\\r';
  }

  const code = ch.charCodeAt(0);

  if (code < 32 || code === 127) {
    return `\\x${byteToLowerHex(code)}`;
  }

  return ch;
}

export function formatPythonString(text) {
  const quote = chooseQuote(text);
  const parts = [quote];

  for (let index = 0; index < text.length; index += 1) {
    parts.push(escapeChar(text[index], quote));
  }

  parts.push(quote);
  return parts.join('');
}

export function formatPythonList(values) {
  const parts = ['['];

  for (let index = 0; index < values.length; index += 1) {
    if (index > 0) {
      parts.push(', ');
    }

    parts.push(formatPythonString(values[index]));
  }

  parts.push(']');
  return parts.join('');
}

