import { basenameFromPath, findChar, stringStartsWith } from '../shared/chars.mjs';

const LONG_OPTIONS = ['--help', '--a'];
const BEGIN_TRANSACTION_WORDS = ['TRANSACTION', 'WORK', 'DEFERRED', 'IMMEDIATE', 'EXCLUSIVE'];

function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A`;
}

function buildHelp(programName) {
  const usage = buildUsage(programName);
  return `${usage}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n`;
}

function buildError(programName, message) {
  const usage = buildUsage(programName);
  return `${usage}\n${programName}: error: ${message}\n`;
}

function isOptionLikeToken(token) {
  return token.length > 1 && token[0] === '-';
}

function collectLongOptionCandidates(optionToken) {
  const matches = [];

  for (let index = 0; index < LONG_OPTIONS.length; index += 1) {
    const candidate = LONG_OPTIONS[index];
    if (stringStartsWith(candidate, optionToken)) {
      matches.push(candidate);
    }
  }

  return matches;
}

function joinUnknownArgs(values) {
  return values.join(' ');
}

function extractProgramName(argv) {
  if (argv.length > 1) {
    return basenameFromPath(argv[1]);
  }

  return 'test2.mjs';
}

function extractAttachedValue(token, equalsIndex) {
  const chars = [];

  for (let index = equalsIndex + 1; index < token.length; index += 1) {
    chars.push(token[index]);
  }

  return chars.join('');
}

export function parseCommandLine(argv) {
  const programName = extractProgramName(argv);
  const unknownArgs = [];
  let parsedValue = null;

  for (let index = 2; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      for (let restIndex = index + 1; restIndex < argv.length; restIndex += 1) {
        unknownArgs.push(argv[restIndex]);
      }
      break;
    }

    if (token.length > 0 && token[0] === '-' && token !== '-') {
      if (token[0] === '-' && token[1] === '-' && token.length > 2) {
        const equalsIndex = findChar(token, '=');
        const optionToken = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
        const candidates = collectLongOptionCandidates(optionToken);

        if (candidates.length > 1) {
          return {
            kind: 'error',
            exitCode: 2,
            output: buildError(programName, `ambiguous option: ${token} could match ${candidates.join(', ')}`),
            stream: 'stderr',
          };
        }

        if (candidates.length === 1) {
          const matchedOption = candidates[0];

          if (matchedOption === '--help') {
            if (equalsIndex !== -1) {
              const explicitValue = extractAttachedValue(token, equalsIndex);
              return {
                kind: 'error',
                exitCode: 2,
                output: buildError(programName, `argument -h/--help: ignored explicit argument '${explicitValue}'`),
                stream: 'stderr',
              };
            }

            return {
              kind: 'help',
              exitCode: 0,
              output: buildHelp(programName),
              stream: 'stdout',
            };
          }

          if (equalsIndex !== -1) {
            parsedValue = extractAttachedValue(token, equalsIndex);
            continue;
          }

          if (index + 1 >= argv.length || isOptionLikeToken(argv[index + 1])) {
            return {
              kind: 'error',
              exitCode: 2,
              output: buildError(programName, 'argument --a: expected one argument'),
              stream: 'stderr',
            };
          }

          parsedValue = argv[index + 1];
          index += 1;
          continue;
        }

        unknownArgs.push(token);
        continue;
      }

      if (token[1] === 'h') {
        if (token.length > 2 && token[2] === '=') {
