  p: 'P',
  q: 'Q',
  r: 'R',
  s: 'S',
  t: 'T',
  u: 'U',
  v: 'V',
  w: 'W',
  x: 'X',
  y: 'Y',
  z: 'Z',
});

export function isLineBreakCharacter(character) {
  return character === '\n' || character === '\r';
}

export function isSpaceButNotLineBreak(character) {
  return (
    character === ' ' ||
    character === '\t' ||
    character === '\f' ||
    character === '\v'
  );
}

export function isWhitespaceCharacter(character) {
  return isSpaceButNotLineBreak(character) || isLineBreakCharacter(character);
}

function isLowercaseAsciiLetter(character) {
  return character >= 'a' && character <= 'z';
}

function isUppercaseAsciiLetter(character) {
  return character >= 'A' && character <= 'Z';
}

function isDigitCharacter(character) {
  return character >= '0' && character <= '9';
}

export function isWordCharacter(character) {
  if (!character) {
    return false;
  }

  return (
    isLowercaseAsciiLetter(character) ||
    isUppercaseAsciiLetter(character) ||
    isDigitCharacter(character) ||
    character === '_'
  );
}

export function toUpperAsciiCharacter(character) {
  const mapped = ASCII_UPPERCASE[character];
  if (mapped === undefined) {
    return character;
  }

  return mapped;
}

export function wordEquals(wordCharacters, literal) {
  if (wordCharacters.length !== literal.length) {
    return false;
  }

  for (let index = 0; index < literal.length; index += 1) {
    if (wordCharacters[index] !== literal[index]) {
      return false;
    }
  }

  return true;
}

export function buildStringFromRange(characters, startIndex, endIndex) {
  const output = [];

  for (let index = startIndex; index < endIndex; index += 1) {
    output.push(characters[index]);
  }

  return output.join('');
}

