export function getProgramName(argv) {
  let candidate = 'test2.mjs';

  if (argv.length > 1 && argv[1]) {
    candidate = argv[1];
  } else if (argv.length > 0 && argv[0]) {
    candidate = argv[0];
  }

  let startIndex = 0;

  for (let index = 0; index < candidate.length; index += 1) {
    const character = candidate[index];
    if (character === '/' || character === '\\') {
      startIndex = index + 1;
    }
  }

  const output = [];
  for (let index = startIndex; index < candidate.length; index += 1) {
    output.push(candidate[index]);
  }

  if (output.length === 0) {
    return candidate;
  }

  return output.join('');
}

export function startsWithText(text, prefix) {
  if (text.length < prefix.length) {
    return false;
  }

  for (let index = 0; index < prefix.length; index += 1) {
    if (text[index] !== prefix[index]) {
      return false;
    }
  }

  return true;
}

export function sliceTextAfter(text, index) {
  const output = [];

  for (let cursor = index; cursor < text.length; cursor += 1) {
    output.push(text[cursor]);
  }

  return output.join('');
}

export function joinTokens(tokens) {
  const output = [];

  for (let index = 0; index < tokens.length; index += 1) {
    if (index > 0) {
      output.push(' ');
    }
    output.push(tokens[index]);
  }

  return output.join('');
}

