import {
  getProgramName,
  joinTokens,
  sliceTextAfter,
  startsWithText,
} from './path_utils.mjs';

function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A\n`;
}

function buildHelp(programName) {
  return (
    buildUsage(programName) +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n'
  );
}

function exitWithHelp(programName) {
  process.stdout.write(buildHelp(programName));
  process.exit(0);
}

function exitWithError(programName, message) {
  process.stderr.write(buildUsage(programName));
  process.stderr.write(`${programName}: error: ${message}\n`);
  process.exit(2);
}

function tokenLooksLikeOption(token) {
  return token.length > 1 && token[0] === '-';
}

export function parseArguments(argv) {
  const programName = getProgramName(argv);
  const extras = [];
  let value = '';
  let hasValue = false;

  for (let index = 2; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      exitWithHelp(programName);
    }

    if (token === '--a') {
      index += 1;

      if (index >= argv.length) {
        exitWithError(programName, 'argument --a: expected one argument');
      }

      const nextToken = argv[index];
      if (tokenLooksLikeOption(nextToken) && nextToken !== '-') {
        exitWithError(programName, 'argument --a: expected one argument');
      }

      value = nextToken;
      hasValue = true;
      continue;
    }

    if (startsWithText(token, '--a=')) {
      value = sliceTextAfter(token, 4);
      hasValue = true;
      continue;
    }

    if (token === '--') {
      extras.push(token);

      for (let extraIndex = index + 1; extraIndex < argv.length; extraIndex += 1) {
        extras.push(argv[extraIndex]);
      }

      break;
    }

    extras.push(token);
  }

  if (!hasValue) {
    exitWithError(programName, 'the following arguments are required: --a');
  }

  if (extras.length > 0) {
    exitWithError(programName, `unrecognized arguments: ${joinTokens(extras)}`);
  }

  return { a: value };
}

