export function isWhitespaceCode(code) {
  return (
    code === 9 ||
    code === 10 ||
    code === 11 ||
    code === 12 ||
    code === 13 ||
    code === 32
  );
}

export function isAsciiDigitCode(code) {
  return code >= 48 && code <= 57;
}

export function isAsciiWordCode(code) {
  return (
    (code >= 48 && code <= 57) ||
    (code >= 65 && code <= 90) ||
    (code >= 97 && code <= 122) ||
    code === 95
  );
}

export function hasNewline(text) {
  for (let index = 0; index < text.length; index += 1) {
    const code = text.charCodeAt(index);
    if (code === 10 || code === 13) {
      return true;
    }
  }

  return false;
}

export function isUnsignedIntegerText(text) {
  if (text.length === 0) {
    return false;
  }

  for (let index = 0; index < text.length; index += 1) {
    if (!isAsciiDigitCode(text.charCodeAt(index))) {
      return false;
    }
  }

  return true;
}

export function trimAsciiWhitespace(text) {
  let start = 0;
  let end = text.length;

  while (start < end && isWhitespaceCode(text.charCodeAt(start))) {
    start += 1;
  }

  while (end > start && isWhitespaceCode(text.charCodeAt(end - 1))) {
    end -= 1;
  }

  return text.slice(start, end);
}

